import { tmpdir } from 'node:os';
import { RetainedContainer } from '../../packages/tui/src/components/retained-item.ts';
import { UserMessageComponent } from '../../packages/coding-agent/src/modes/interactive/components/user-message.ts';
import { AssistantMessageComponent } from '../../packages/coding-agent/src/modes/interactive/components/assistant-message.ts';
import { Markdown } from '../../packages/tui/src/components/markdown.ts';
import { initTheme } from '../../packages/coding-agent/src/modes/interactive/theme/theme.ts';
import { createTranscriptItems } from '../../scripts/bench/fixtures.ts';
import { detectCacheMiss } from '../../packages/coding-agent/src/core/cache-stats.ts';
assert.equal(tmpdir(), process.env.TMPDIR);
initTheme('dark');
const zeroUsage={input:0,output:0,cacheRead:0,cacheWrite:0,totalTokens:0,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}};
function message(text: string) {return {role:'assistant',content:[{type:'text',text}],api:'benchmark',provider:'benchmark',model:'benchmark',usage:zeroUsage,stopReason:'stop',timestamp:0} as any;}
function summarize(samples:number[]){const sorted=samples.slice().sort((a,b)=>a-b);return {p50Ms:sorted[Math.ceil(sorted.length*.5)-1],p95Ms:sorted[Math.ceil(sorted.length*.95)-1],samples};}
const resize=[];
for (const count of process.argv.includes('--markdown-only') ? [] : [5000,50000]) {
  const transcript=new RetainedContainer(), source=createTranscriptItems(count);
  for(let i=0;i<count;i++)transcript.addRetainedChild(i%2?new AssistantMessageComponent(message(source[i]!)):new UserMessageComponent(source[i]!),{id:'history-'+i,version:1,completed:true});
  const initialStart=performance.now();transcript.renderViewportTail(120,40);const initialMs=performance.now()-initialStart;
  const samples=[],measuredCounts=[],visitedCounts=[];let width=120;
  for(let i=0;i<8;i++){width=width===120?96:120;const t=performance.now();const frame=transcript.renderViewportTail(width,40);if(i>1){samples.push(performance.now()-t);measuredCounts.push(frame.measuredItems);visitedCounts.push(frame.visitedItems);}}
  const index=transcript.getViewportIndexStats();
  transcript.clear();globalThis.gc?.();
  resize.push({count,initialMs,resize:summarize(samples),measuredCounts,visitedCounts,index,referencesAfterClear:transcript.getRetainedLifecycleReferenceCounts()});
}
const style=(value:string)=>value;
const theme={heading:style,link:style,linkUrl:style,code:style,codeBlock:style,codeBlockBorder:style,quote:style,quoteBorder:style,hr:style,listBullet:style,bold:style,italic:style,strikethrough:style,underline:style};
const markdown=[];
for(const kib of [16,64])for(const kind of ['plain','code','table']){
  const chunk=kind==='plain'?'ordinary words repeated ':kind==='code'?'const value = 123;\n':'| row | value |\n';
  let source=(kind==='code'?'```ts\n':kind==='table'?'| key | value |\n| --- | --- |\n':'')+chunk.repeat(Math.ceil(kib*1024/chunk.length));
  if(kind==='plain') source=source.trimEnd();
  const metrics:any={incrementalEligibleUpdates:0,incrementalUpdates:0,fullFallbacks:0,sourceCharactersReparsed:0,sourceCharactersRewrapped:0,parserTokensReused:0,parserTokensRebuilt:0,renderedPrefixLinesReused:0,tailLinesRebuilt:0,cachedTokenCount:0,cachedRenderedLines:0,cachedSourceCharacters:0,lastFallbackReason:'none'};
  const md=new Markdown(source,1,0,theme,undefined,{incrementalRenderCache:true},metrics);
  md.render(120);
  const samples=[];
  for(let i=0;i<40;i++) {source+=kind==='plain'?' extra':kind==='code'?'const next = 1;\n':'| next | 1 |\n';const t=performance.now();md.setText(source);md.render(120);if(i>=10)samples.push(performance.now()-t);}
  md.invalidate();
  markdown.push({kind,kib,sourceCharacters:source.length,timing:summarize(samples),metrics});
}
const cacheScan=[];
const models={getModel(){return {cost:{cacheRead:0.1}};}};
for(const count of process.argv.includes('--markdown-only') ? [] : [1000,10000,50000]){
  const entries:any[]=[];
  for(let i=0;i<count;i++){const msg=message('');msg.timestamp=i*1000;msg.usage={input:50000,output:1,cacheRead:1000,cacheWrite:0,totalTokens:51001,cost:{input:.1,output:0,cacheRead:.001,cacheWrite:0,total:.101}};entries.push({type:'message',message:msg});}
  const current=message('');current.usage=entries[count-1].message.usage;current.timestamp=count*1000;
  const samples=[];
  for(let i=0;i<15;i++){const t=performance.now();assert.ok(detectCacheMiss(entries,current,models));if(i>=5)samples.push(performance.now()-t);}
  cacheScan.push({count,timing:summarize(samples)});
}
console.log(JSON.stringify({benchmark:'audit-boundaries',node:process.version,resize,markdown,cacheScan},null,2));

