import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { buildPlan } from '../../scripts/build.mjs';
const repo=process.cwd(),root=import.meta.dirname;
const buffer=Buffer.allocUnsafe(1024*1024);
function digest(file){const hash=createHash('sha256'),fd=fs.openSync(file,'r');try{for(;;){const length=fs.readSync(fd,buffer,0,buffer.length,null);if(!length)break;hash.update(buffer.subarray(0,length));}}finally{fs.closeSync(fd);}return hash.digest('hex');}
function manifest(files){files.sort();const rows=files.map(file=>({path:path.relative(repo,file).replaceAll('\\','/'),bytes:fs.statSync(file).size,sha256:digest(file)}));return {files:rows.length,bytes:rows.reduce((sum,row)=>sum+row.bytes,0),sha256:createHash('sha256').update(JSON.stringify(rows)).digest('hex')};}
const sources=execFileSync('git',['ls-files','-z','--','packages','.sp','scripts/superpi.mjs','scripts/build.mjs','package.json','package-lock.json','tsconfig*.json'],{encoding:'utf8'}).split('\0').filter(Boolean).map(file=>path.join(repo,file));
const outputs=[];
for(const item of buildPlan(repo,undefined,true)){
 const pending=[path.join(item.cwd,'dist')],files=[];
 while(pending.length){const name=pending.pop(),stat=fs.lstatSync(name);if(stat.isSymbolicLink())throw new Error('Unexpected runtime link '+name);if(stat.isDirectory()){for(const child of fs.readdirSync(name))pending.push(path.join(name,child));}else files.push(name);}
 outputs.push({package:item.name,script:item.script,...manifest(files)});
}
const productionDiff=execFileSync('git',['diff','--','packages','.sp','scripts/superpi.mjs','scripts/build.mjs','package.json','package-lock.json'],{encoding:'utf8'});
if(productionDiff.trim())throw new Error('Unexpected production modifications');
const result={base:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),node:process.version,productionSources:manifest(sources),lockfileSha256:digest(path.join(repo,'package-lock.json')),outputs,
 cliSha256:digest(path.join(repo,'packages/coding-agent/dist/cli.js')),benchmarkSources:manifest(['cli-lifecycle.mjs','cli-lifecycle-probe.mjs','cli-lifecycle-extension.mjs'].map(file=>path.join(repo,'scripts/bench',file))),capturedAt:new Date().toISOString()};
fs.writeFileSync(path.join(root,'build-snapshot.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));

