import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { tmpdir } from 'node:os';
const root=import.meta.dirname,repo=path.resolve(root,'../..'),mode=process.argv[2];
assert.ok(mode==='regular'||mode==='fullscreen');
assert.equal(tmpdir(),root);
const label=process.argv[3]??mode;assert.match(label,/^[a-z-]+$/);
const report=path.join(root,'native-'+label+'.jsonl');
fs.writeFileSync(report,JSON.stringify({phase:'parent-entry',pid:process.pid,stdinTTY:process.stdin.isTTY??false,stdoutTTY:process.stdout.isTTY??false})+'\n',{flag:'wx'});
assert.equal(process.stdin.isTTY,true);assert.equal(process.stdout.isTTY,true);
const home=path.join(root,'native-'+label),agent=path.join(home,'agent');fs.mkdirSync(path.join(agent,'config'),{recursive:true});
fs.writeFileSync(path.join(agent,'config/settings.json'),JSON.stringify({quietStartup:true,theme:'dark',terminal:{showTerminalProgress:false},compaction:{enabled:false}}));
const env={PATH:process.env.PATH,SystemRoot:process.env.SystemRoot,WINDIR:process.env.WINDIR,COMSPEC:process.env.COMSPEC,PATHEXT:process.env.PATHEXT,
 HOME:home,USERPROFILE:home,XDG_CONFIG_HOME:home,SP_CODING_AGENT_DIR:agent,SP_CODING_AGENT_SESSION_DIR:path.join(home,'sessions'),TMP:root,TEMP:root,TMPDIR:root,SP_OFFLINE:'1',SP_SKIP_VERSION_CHECK:'1',PF_NATIVE_REPORT:report};
const child=spawn(process.execPath,['--import',pathToFileURL(path.join(root,'native-preload.mjs')).href,path.join(repo,'scripts/superpi.mjs'),'--offline','--no-session','--tui-mode',mode,'--extension',path.join(repo,'scripts/bench/cli-lifecycle-extension.mjs')],{cwd:home,env,windowsHide:true,stdio:'inherit'});
fs.appendFileSync(report,JSON.stringify({phase:'spawn',pid:child.pid,started:new Date().toISOString()})+'\n');
let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;child.kill();},120000);
const code=await new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',resolve);});clearTimeout(timeout);
fs.appendFileSync(report,JSON.stringify({phase:'closed',pid:child.pid,code,timedOut,finished:new Date().toISOString()})+'\n');
assert.equal(code,0);assert.equal(timedOut,false);
const records=fs.readFileSync(report,'utf8').trim().split('\n').map(JSON.parse);
assert.equal(records.find(row=>row.phase==='native-exit')?.raw,false);
console.log('PF_NATIVE_COMPLETE:'+mode);

